document.addEventListener("DOMContentLoaded",(async()=>{const{pages:t=[]}=await chrome.storage.local.get("pages"),e=(new Date).toISOString().split("T")[0],n=t.filter((t=>t.timestamp.startsWith(e)));document.getElementById("pageCount").textContent=n.length,document.getElementById("viewHistory").addEventListener("click",(()=>{chrome.tabs.create({url:"https://your-website.com/history"})}))}));